import{_ as i,o as n,c as a,aj as l}from"./chunks/framework.BdtAaXf2.js";const p="/assets/image-20250208224404854.BEX4FGKm.png",e="/assets/image-20250208225612809.Lc1suQwl.png",t="/assets/image-20250208224438567.CXu23vXt.png",h="/assets/image-20250208225401478.BqBJBVzz.png",k="/assets/image-20250208231342642.BxPfZXGv.png",r="/assets/image-20250208231411534.fQxQul-4.png",E="/assets/image-20250208231500267.oDpf5CtQ.png",d="/assets/image-20250209095250827.CORyTjJU.png",o="/assets/image-20250209095502324.C3Z1oPUJ.png",g="/assets/image-20250209104450026.BAGTU_62.png",c="/assets/image-20250209104513583.B6K_GXg2.png",y="/assets/image-20250209104549805.BLQWkvpq.png",b="/assets/image-20250209105304376.C3NRoL2I.png",u="/assets/image-20250209112440351.C2Cexefo.png",F="/assets/image-20250209112607971.3QQS7y8z.png",m="/assets/image-20250209133623676.DMXuZ4PS.png",C="/assets/image-20250209133103645.BglyhYID.png",B="/assets/image-20250209133521557.BcYrOU7N.png",A="/assets/image-20250209140233851.BjKl0tBE.png",T=JSON.parse('{"title":"HarmonyOSNext 端云一体化（6）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（6）/HarmonyOSNext 端云一体化（6）.md","filePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（6）/HarmonyOSNext 端云一体化（6）.md","lastUpdated":1739083342000,"__rawMarkdown":"# HarmonyOSNext 端云一体化（6）\\n\\n之前的文章中把云数据库、云存储都讲过了，这一章节要讲解的是**云函数**。\\n\\n## 云函数介绍\\n\\n云函数其实就是serverless技术。可以理解云函数就实现传统后端中的具体业务，而无需关心服务器购买、部署、安全、性能等一系\\n\\n列相关问题，专注于具体的业务开发。HarmonyOS Next的云函数采用的是typescript的语法，这对熟悉js或者熟悉ArkTs的同学来说\\n\\n都很容易上手。\\n\\n另外云函数具有调用其他云函数、调用第三方接口、调用云存储、调用云数据库的能力。对于段云一体化开发的应用来说，可以根据这样的场景来使用云函数。\\n\\n1. 简单的数据库查询、云端文件的管理可以直接使用客户端操作的方式。\\n2. 繁琐或者涉及安全的操作，可以把业务抽离到云函数端，这样更加容易管理项目。\\n\\n本章节也会讲解如何云函数的开发、创建、调试、部署，以及在云函数端调用其他云函数、调用第三方接口、调用云存储、调用云\\n\\n数据库。\\n\\n\\n\\n## 创建云函数\\n\\n可以选择创建云函数或者云对象。这里建议选择云对象更加方便业务逻辑的实现。为什么呢，举个例子。书籍的crud刚好放在一个对象中，增、删、改、查都可以做个一个对象的属性存在，更加容易方便管理。比如以下示例。\\n\\n- 云函数一览\\n\\n  ```typescript\\n  // 云函数\\n  let myHandler = async function (event, context, callback, logger) {\\n    //   这里写不同的业务逻辑，都是都耦合在一个myHandler中\\n    callback();\\n  };\\n  \\n  export { myHandler }\\n  ```\\n\\n- 云对象一览\\n\\n  ```typescript\\n  export class Book {\\n    //   增加\\n    add() {\\n      return {};\\n    }\\n  \\n    //   删除\\n    delete() {\\n    }\\n  \\n    //   修改\\n    update() {\\n    }\\n  \\n    //   查询\\n    query() {\\n    }\\n  }\\n  ```\\n\\n\\n\\n新建云对象，云对象名称为book。\\n\\n![image-20250208224404854](assets/image-20250208224404854.png)\\n\\n得到以下新文件，其中 `book.ts` 是编写云对象book具体业务逻辑的。`function-config.json`是关于该云对象的相关配置如是否鉴权等。`package.json`是该云对象的描述文件，具体作用类似 `oh-package.json`,后续安装第三方依赖也会在这里登记信息。\\n\\n![image-20250208225612809](assets/image-20250208225612809.png)\\n\\n\\n\\n### function-config.json\\n\\n文件内容如下。\\n\\n```json\\n{\\n  \\"handler\\": \\"book.Book\\",\\n  \\"functionType\\": 1,\\n  \\"triggers\\": [\\n    {\\n      \\"type\\": \\"http\\",\\n      \\"properties\\": {\\n        \\"enableUrlDecode\\": true,\\n        \\"authFlag\\": \\"true\\",\\n        \\"authAlgor\\": \\"HDA-SYSTEM\\",\\n        \\"authType\\": \\"apigw-client\\"\\n      }\\n    }\\n  ]\\n}\\n```\\n\\n相关解析如下\\n\\n- handler 表示云对象的入口\\n\\n- functionType 表示函数类型，“0”表示云函数，“1”表示云对象。“functionType”的值为创建时自动生成，不可手动修改，否则将导致云函数部署失败。\\n\\n- triggers 表示触发云对象的函数\\n\\n  - type：触发器类型，配置为“http”。\\n\\n  - properties：触发器属性，属性参数如下表所示。\\n\\n    | 参数            | 说明                                                         |\\n    | :-------------- | :----------------------------------------------------------- |\\n    | enableUrlDecode | 通过HTTP触发器触发函数时，对于contentType为“application/x-www-form-urlencoded”的触发请求，是否使用URLDecoder对请求body进行解码再转发到函数中。true：启用。false：不启用。 |\\n    | authFlag        | 是否鉴权，默认为true。                                       |\\n    | authAlgor       | 鉴权算法，默认为HDA-SYSTEM。                                 |\\n    | authType        | HTTP触发器的认证类型。apigw-client：端侧网关认证，适用于来自APP客户端侧（即本地应用或者项目）的函数调用。cloudgw-client：云侧网关认证，适用于来自APP服务器侧（即云函数）的函数调用。 |\\n\\n### oh-package.json\\n\\n文件内容如下。\\n\\n```json\\n{\\n  \\"name\\": \\"book\\",\\n  \\"version\\": \\"1.0.0\\",\\n  \\"description\\": \\"\\",\\n  \\"scripts\\": {\\n    \\"test\\": \\"echo \\\\\\"Error: no test specified\\\\\\" && exit 1\\"\\n  },\\n  \\"author\\": \\"\\",\\n  \\"license\\": \\"ISC\\",\\n  \\"dependencies\\": {\\n  }\\n}\\n```\\n\\n相关解释如下。\\n\\n- **`name`**：表示项目的名称\\n- **`version`**：项目的版本号\\n- **`description`**：项目的描述\\n- **`scripts`**：一个包含各种脚本命令的对象\\n- **`author`**：项目作者信息\\n- **`license`**：项目所使用的开源许可证，这里是 `\\"ISC\\"`\\n- **`dependencies`**：项目的依赖信息\\n\\n### book.ts\\n\\nbook.ts的文件解析如下。\\n\\n1. **methods1**表示云对象具体的方法，可以有多个。\\n2. **params1**、**params2**是传递给该云对象的参数\\n3. **return** 的内容是返回给云对象的调用者\\n\\n![image-20250208224438567](assets/image-20250208224438567.png)\\n\\n## 调试云函数/对象\\n\\n在开发云对象时，经常需要编写繁琐的业务逻辑，那么就必不可少对象的调试。DevEco Studio 内置了云对象的调试面板。按照以下步骤操作就可以方便对云对象进行调试了。\\n\\n1. 启动云对象调试，鼠标右键你要调试的云对象、选择 **Debug ‘book‘**\\n\\n   ![image-20250208225401478](assets/image-20250208225401478.png)\\n\\n2. 打开云对象调试面板\\n\\n   ![image-20250208231342642](assets/image-20250208231342642.png)\\n\\n3. 云对象日志面板\\n\\n   当我们在云对象中使用console.log调试代码时，日志的输出在这个位置。\\n\\n   ![image-20250208231411534](assets/image-20250208231411534.png)\\n\\n需要注意的是当我们修改了云对象的代码时，都需要重新点击 **debug book**\\n\\n![image-20250208231500267](assets/image-20250208231500267.png)\\n\\n\\n\\n## 部署云对象\\n\\n当云对象开发完毕后，想要客户端调用或者上线生产环境，都需要部署上去。右键你的云对象，选择 **Deploy ‘book’**  就可以把你的云对象部署到云端了。你也可以鼠标右键 **cloudfouctions** 部署或者同步所有的云对象。\\n\\n> 如果想要把之前部署到云端的云对象下载下来，选择 **Sync book**  即可\\n\\n![image-20250209095250827](assets/image-20250209095250827.png)\\n\\n部署成功，右下角会有相应的提示。\\n\\n![image-20250209095502324](assets/image-20250209095502324.png)\\n\\n## 客户端调用云对象\\n\\n当我们创建好了云对象后，就可以使用客户端直接调用云对象的方法了。\\n\\n如果是客户端调用云函数，可以参考以下代码。\\n\\n核心代码如下。\\n\\n```typescript\\ntry {\\n  const res = await cloudFunction.call({\\n    // 云对象的名称，这个和你创建的云对象文件名一致\\n    name: \\"book\\",\\n    data: {\\n      // book云对象的methods1方法\\n      method: \'method1\',\\n      // 传递给method1的参数\\n      params: [\'a\', \'b\'],\\n    }\\n  })\\n  AlertDialog.show({ message: JSON.stringify(res, null, 2) })\\n} catch (e) {\\n  console.error(e.message + \\" \\" + e.code)\\n}\\n```\\n\\n这里重点讲解的是**客户端调用云对象**。\\n\\nDevEco Studio 提供了方便的方式实现客户端调用云对象的功能。可以让我们想调用普通对象方法一样，直接调用云对象！\\n\\n具体操作步骤如下。\\n\\n1. 依据云对象 ，在客户端生成云对象的调用模型。  鼠标右键你的云对象 Book。选择 **Generate Invoke Interface**\\n\\n   ![image-20250209104450026](assets/image-20250209104450026.png)\\n\\n2. 选择存放该模型文件的路径\\n\\n   ![image-20250209104513583](assets/image-20250209104513583.png)\\n\\n3. 生成成功后，得到两个关键文件 `ImportObject.ts` 和 `Book.ets`\\n\\n   ![image-20250209104549805](assets/image-20250209104549805.png)\\n\\n   `ImportObject.ts`文件的主要作用是利用代理Proxy的方式，当用户调用`Book.method1` 方法时，在内部执行了 云函数的调用方法`cloudFunction.call`方法。为我们调用云对象提供了便利。代码如下。\\n\\n   ```typescript\\n   /*\\n    * Copyright (c) Huawei Technologies Co., Ltd. 2020-2024. All rights reserved.\\n    * Generated by the Cloud Object compiler. DO NOT EDIT!\\n    */\\n   import type { BusinessError } from \'@kit.BasicServicesKit\';\\n   import { cloudFunction } from \'@kit.CloudFoundationKit\';\\n   \\n   export interface CloudObjectLikely {\\n     name: string;\\n   }\\n   \\n   function mockMethod<T extends CloudObjectLikely>(target: T, version: string,\\n     prop: string | symbol): (...args: unknown[]) => Promise<unknown> {\\n     return async (...args: unknown[]) => new Promise((resolve, reject) => {\\n       cloudFunction.call({\\n         name: target.name,\\n         version: version,\\n         data: {\\n           method: prop,\\n           params: args\\n         }\\n       }).then((value: cloudFunction.FunctionResult) => {\\n         resolve(value.result);\\n       }).catch((err: BusinessError) => {\\n         reject(err);\\n       });\\n     });\\n   }\\n   \\n   export function importObject<T extends CloudObjectLikely>(tClass: new () => T, version = \'$latest\'): T {\\n     return new Proxy<T>(new tClass(), {\\n       get(target, prop): (...args: unknown[]) => Promise<unknown> {\\n         return mockMethod<T>(target, version, prop);\\n       }\\n     });\\n   }\\n   \\n   ```\\n\\n   `Book.ets`文件的作用是参考云对象Book的模型，生成对应的类，方便我们调用云对象。代码如下。\\n\\n   ```typescript\\n   /*\\n    * Copyright (c) Huawei Technologies Co., Ltd. 2020-2024. All rights reserved.\\n    * Generated by the Cloud Object compiler. DO NOT EDIT!\\n    */\\n   import type { CloudObjectLikely } from \'../ImportObject\';\\n   \\n   export class Book implements CloudObjectLikely {\\n       public name = \'book\';\\n       public async method1(param1: any, param2: any): Promise<{\\n           simple: string;\\n           param1: any;\\n           param2: any;\\n       }> {\\n   \\n           return Promise.reject(new Error(\'Method not implemented.\'));\\n       }\\n   }\\n   ```\\n\\n   \\n\\n4. 最后，在客户端中需要导入 `Book` 和 `importObject`，再进行调用\\n\\n   ```jsx\\n   // 这里需要对Book进行重命名，因为和之前的数据库类型Book重名了\\n   import { Book as BookCloudObj } from \'../cloudobject/book/Book\';\\n   import { importObject } from \'../cloudobject/ImportObject\';\\n   \\n         Button(\\"调用云对象14的方法\\")\\n           .onClick(this.fn14)\\n           \\n       fn14 = async () => {\\n       try {\\n         let bookObj = importObject(BookCloudObj); // 使用importObject实例化BookCloudObj的代理\\n         const res = await bookObj.method1(\'100\', \'200\')\\n         AlertDialog.show({ message: JSON.stringify(res, null, 2) })\\n       } catch (e) {\\n         console.error(e.message + \\" \\" + e.code)\\n       }\\n     }\\n   ```\\n\\n5. 调用结果如图。\\n\\n   ![image-20250209105304376](assets/image-20250209105304376.png)\\n\\n\\n\\n## 云对象调用云对象\\n\\n在实际开发中，一般情况下，某个具体的业务是存在某个具体的云对象中的，但是必不可少的会出现业务之间的关联。比如查询某一个作者编写过的所有的书籍。作者可以是一个单独的云对象，书籍也是一个单独的云对象，这样就会出现云对象之间调用云对象 需求。我们可以通过 book云对象调用auth云对象来演示。\\n\\n> 由于云对象部署到云端后是各自独立的，因此这里不能简单的将多个云对象看成是同一个目录之间的关系，也就是不能 云对象a使用相对路径直接导入云对象b ！\\n\\n1. 新建auth云对象 *这个看上面的创建book云对象步骤即可*\\n\\n2. 调整auth云对象的网关设置\\n\\n   `function-config.json` 中的**authType**设置为 `cloudgw-client`\\n\\n   ```json\\n   \\"authType\\": \\"cloudgw-client\\"\\n   ```\\n\\n3. 编写auth云对象逻辑代码\\n\\n   ```js\\n   export class Auth {\\n     getName(firstName, lastName) {\\n       return { firstName, lastName, fullName: firstName + lastName };\\n     }\\n   }\\n   ```\\n\\n4. book安装云对象三方库，注意需要在book云对象目录下安装\\n\\n   ```sh\\n   npm install @hw-agconnect/cloud-server\\n   ```\\n\\n   ![image-20250209112440351](assets/image-20250209112440351.png)\\n\\n5. book调用auth云对象\\n\\n   ```js\\n   import { cloud } from \\"@hw-agconnect/cloud-server\\";\\n   \\n   export class Book {\\n     async method1(param1, param2) {\\n   \\n       const res = await cloud.function().call({\\n         // 云对象的名称\\n         name: \\"auth\\",\\n   \\n         data: {\\n           // 云对象的方法\\n           method: \\"getName\\",\\n           // 传递的参数\\n           params: [\'万\', \\"大妈\\"]\\n         }\\n       });\\n   \\n       return {\\n         \\"simple\\": \\"example\\",\\n         param1,\\n         param2,\\n         res\\n       };\\n     }\\n   }\\n   ```\\n\\n6. auth和book都部署到云端\\n\\n7. 客户端测试调用，验证效果\\n\\n   ![image-20250209112607971](assets/image-20250209112607971.png)\\n\\n   \\n\\n   支持，便完成了云对象调用云对象了。\\n\\n\\n\\n## 云对象调用云存储\\n\\n在翻阅了相关文档后，发现云对象对于云存储的支持程度远不够，这里略过。\\n\\n\\n\\n## 云对象调用云数据库\\n\\n云对象中也是需要引入 `@hw-agconnect/cloud-server` 来操作云数据库的。我们按照以下步骤进行操作。实现查询云对象中查\\n\\n询数据库的功能。\\n\\n1. 首先在云对象book处新建一个文件夹model，用来存放即将生成的文件\\n\\n   ![image-20250209133623676](assets/image-20250209133623676.png)\\n\\n2. 在云端生成操作Book表格的云对象模块。这里 DevEco Studio会自动帮我们生成。选择**Generate Server Model**。\\n\\n   ![image-20250209133103645](assets/image-20250209133103645.png)\\n\\n   然后选择生成的路径。\\n\\n   \\n\\n   ![image-20250209133521557](assets/image-20250209133521557.png)\\n\\n3. 得到文件 `model/book.ts` ,这里为了和之前的`book.ts`区分，我们把它名称修改成 `model/bookModel.ts`。文件中的类名也修改成 `BookModel`\\n\\n   ```typescript\\n   /*\\n    * Copyright (c) Huawei Technologies Co., Ltd. 2020-2023. All rights reserved.\\n    * Generated by the CloudDB ObjectType compiler. DO NOT EDIT!\\n    */\\n   \\n   class BookModel {\\n     id: number;\\n     name: string;\\n     price: number;\\n     publish: Date;\\n     hot: boolean;\\n     cover: string;\\n   \\n     constructor() {\\n     }\\n   \\n     getFieldTypeMap(): Map<string, string> {\\n       let fieldTypeMap = new Map<string, string>();\\n       fieldTypeMap.set(\'id\', \'Integer\');\\n       fieldTypeMap.set(\'name\', \'String\');\\n       fieldTypeMap.set(\'price\', \'Double\');\\n       fieldTypeMap.set(\'publish\', \'Date\');\\n       fieldTypeMap.set(\'hot\', \'Boolean\');\\n       fieldTypeMap.set(\'cover\', \'String\');\\n       return fieldTypeMap;\\n     }\\n   \\n     getClassName(): string {\\n       return \'Book\';\\n     }\\n   \\n     getPrimaryKeyList(): string[] {\\n       let primaryKeyList: string[] = [];\\n       primaryKeyList.push(\'id\');\\n       return primaryKeyList;\\n     }\\n   \\n     getIndexList(): string[] {\\n       let indexList: string[] = [];\\n       indexList.push(\'id\');\\n       indexList.push(\'price\');\\n       return indexList;\\n     }\\n   \\n     getEncryptedFieldList(): string[] {\\n       let encryptedFieldList: string[] = [];\\n       return encryptedFieldList;\\n     }\\n   \\n     setId(id: number): void {\\n       this.id = id;\\n     }\\n   \\n     getId(): number {\\n       return this.id;\\n     }\\n   \\n     setName(name: string): void {\\n       this.name = name;\\n     }\\n   \\n     getName(): string {\\n       return this.name;\\n     }\\n   \\n     setPrice(price: number): void {\\n       this.price = price;\\n     }\\n   \\n     getPrice(): number {\\n       return this.price;\\n     }\\n   \\n     setPublish(publish: Date): void {\\n       this.publish = publish;\\n     }\\n   \\n     getPublish(): Date {\\n       return this.publish;\\n     }\\n   \\n     setHot(hot: boolean): void {\\n       this.hot = hot;\\n     }\\n   \\n     getHot(): boolean {\\n       return this.hot;\\n     }\\n   \\n     setCover(cover: string): void {\\n       this.cover = cover;\\n     }\\n   \\n     getCover(): string {\\n       return this.cover;\\n     }\\n   \\n     static parseFrom(inputObject: any): BookModel {\\n       let result = new BookModel();\\n       if (!inputObject) {\\n         return result;\\n       }\\n       if (inputObject.id) {\\n         result.id = inputObject.id;\\n       }\\n       if (inputObject.name) {\\n         result.name = inputObject.name;\\n       }\\n       if (inputObject.price) {\\n         result.price = inputObject.price;\\n       }\\n       if (inputObject.publish) {\\n         result.publish = new Date(inputObject.publish);\\n       }\\n       if (inputObject.hot) {\\n         result.hot = inputObject.hot;\\n       }\\n       if (inputObject.cover) {\\n         result.cover = inputObject.cover;\\n       }\\n       return result;\\n     }\\n   }\\n   \\n   export { BookModel };\\n   ```\\n\\n4. 新建文件`bookController.ts`，负责组合 对book实例的CURD操作。\\n\\n   ```typescript\\n   import { cloud, CloudDBCollection } from \'@hw-agconnect/cloud-server\'; //引入Server SDK依赖\\n   import { BookModel } from \'./model/BookModel\'; //BookModel为对象类型名\\n   \\n   // ZONE_NAME为存储区名称\\n   const ZONE_NAME = \\"Study\\";\\n   \\n   export class BookCtroller {\\n     collection: CloudDBCollection<BookModel>;\\n   \\n     constructor() {\\n       this.collection = cloud.database({ zoneName: ZONE_NAME }).collection(BookModel);\\n     }\\n   \\n     //查询数据\\n     async queryBooks() {\\n       let query = this.collection.query();\\n       return await query.get();\\n     }\\n   \\n     //更新数据\\n     async upsertBooks(records: BookModel[]) {\\n       return await this.collection.upsert(records);\\n     }\\n   \\n     //删除数据\\n     async deleteBooks(records: BookModel[]) {\\n       return await this.collection.delete(records);\\n     }\\n   }\\n   ```\\n\\n5. 最后在云对象book中添加一个查询方法 query。\\n\\n   ```typescript\\n     // 查询数据库\\n     async query() {\\n       let bookCtroller = new BookCtroller();\\n       const result = await bookCtroller.queryBooks()\\n       return {\\n         result\\n       }\\n     }\\n   ```\\n\\n6. 测试调用\\n\\n   ![image-20250209140233851](assets/image-20250209140233851.png)\\n\\n\\n\\n\\n\\n其他的数据库操作可以基于该模式进行拓展。\\n\\n\\n\\n\\n\\n## 云对象调用第三方api\\n\\n如想要调用其他的api，比较简单的方式可以直接安装axios，然后像调用接口一样使用axios即可。\\n\\n\\n\\n\\n\\n## 总结\\n\\n1. **云函数介绍**：云函数即 serverless 技术，采用 TypeScript 语法，开发者无需关注服务器相关问题，专注业务开发。它具备调用其他云函数、第三方接口、云存储及云数据库的能力。简单数据库查询等操作可在客户端进行，繁琐或涉及安全的操作适合放在云函数端。\\n2. **创建云函数**：建议选择创建云对象，以书籍的 CRUD 为例，将其放在一个对象中更便于管理业务逻辑。创建云对象后会生成 `book.ts`（编写业务逻辑）、`function - config.json`（云对象配置，如入口、函数类型、触发器等）、`package.json`（类似`oh - package.json`，记录项目信息及依赖）。\\n3. **调试云函数 / 对象**：在 DevEco Studio 中，右键要调试的云对象选择 “Debug ‘book’” 启动调试，可在云对象调试面板和日志面板查看相关信息。修改代码后需重新点击 “debug book”。\\n4. **部署云对象**：开发完成后，右键云对象选择 “Deploy ‘book’” 可部署到云端，也可右键 “cloudfouctions” 部署或同步所有云对象。若要下载已部署的云对象，选择 “Sync book”。\\n5. **客户端调用云对象**：DevEco Studio 提供便捷方式，通过右键云对象选择 “Generate Invoke Interface” 生成调用模型，选择存放路径后得到`ImportObject.ts`（利用代理执行云函数调用方法）和`Book.ets`（参考云对象模型生成的类）。在客户端导入相关文件后即可调用云对象方法。\\n6. **云对象调用云对象**：以 book 云对象调用 auth 云对象为例，需新建 auth 云对象并调整网关设置（`function - config.json`中**authType**设为`cloudgw - client`），编写 auth 云对象逻辑代码，在 book 云对象目录下安装云对象三方库`@hw - agconnect/cloud - server`，然后在 book 云对象中调用 auth 云对象，最后将两个云对象部署到云端并在客户端测试调用。\\n7. **云对象调用云存储**：文档显示云对象对云存储支持不足，故略过。\\n8. **云对象调用云数据库**：在云对象 book 处新建文件夹 model，通过 DevEco Studio 生成操作 Book 表格的云对象模块，得到`bookModel.ts`文件并修改相关内容。新建`bookController.ts`文件负责组合对 book 实例的 CURD 操作，最后在云对象 book 中添加查询方法并进行测试调用。\\n9. **云对象调用第三方 api**：调用其他 api 较简单的方式是安装 axios，然后像调用接口一样使用。\\n\\n---\\n\\n\\n\\n## 参考文档\\n\\n1. [云侧通过SDK使用云数据库](https://developer.huawei.com/consumer/cn/doc/AppGallery-connect-Guides/agc-clouddb-via-sdk-server-0000001569149001)\\n2. [@hw-agconnect/cloud-server](https://www.npmjs.com/package/@hw-agconnect/cloud-server#cloud-functions)\\n3. [端云一体化开发](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/agc-harmonyos-clouddevguide-V5)\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n"}'),D={name:"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（6）/HarmonyOSNext 端云一体化（6）.md"};function v(f,s,q,j,x,O){return n(),a("div",null,[...s[0]||(s[0]=[l("",70)])])}const _=i(D,[["render",v]]);export{T as __pageData,_ as default};
